---@module 'hl'

-- You can put custom rules here

-- Window/layer rules: https://wiki.hyprland.org/Configuring/Window-Rules/

-- Workspace rules: https://wiki.hyprland.org/Configuring/Workspace-Rules/

-- TODO: manual review: focus_on_activate = true

-- Force MegaSync into XWayland

-- Float the window so dialogs don’t get tiled

hl.window_rule({
    name  = "megasync-float",
    match = {
        class = "MEGAsync",
    },
    float = true,
    fullscreen = true,
})

-- Conky under XWayland usually has class "Conky"

hl.window_rule({
    name  = "conky-rules",
    match = {
        class = "^(Conky)$",
    },
    float = true,
    border_size = 0,
    no_focus = true,
    no_anim = true,
    no_blur = true,
})

hl.window_rule({
    name  = "ulauncher-rules",
    match = {
        class = "^(Ulauncher)$",
    },
    no_blur = true,
    border_size = 0,
    float = true,
})

-- Force flameshot to start correctly across all monitors while maintaining position

hl.window_rule({
    name  = "flameshot-rules",
    match = {
        class = "^(flameshot)$",
        title = "^(flameshot)$",
    },
    monitor = "eDP-1",
    move = { 0, 0 },
    pin = true,
    float = true,
    no_anim = true,
    fullscreen_state = 1,
})

-- Satty screenshot editor (Super+Shift+S): float it centred on the screen you
-- are working on instead of tiling it next to your windows.
hl.window_rule({
    name  = "satty-editor",
    match = {
        class = "^(com.gabm.satty)$",
    },
    float = true,
    center = true,
    size = { "(monitor_w*0.8)", "(monitor_h*0.8)" },
})


-- Suppress full-monitor takeover when browsers request fullscreen (e.g. pressing 'f' on YouTube)
-- Browsers launch normally in standard tiled mode, and pressing 'f' on YouTube expands inside its split tile
hl.window_rule({
    name  = "browser-suppress-fullscreen",
    match = {
        class = "^(brave-browser|chromium-browser|firefox|zen-browser|google-chrome)$",
    },
    suppress_event = "fullscreen",
})






